export function getPostBySlug(slug) {
    return posts.find((p) => p.slug === slug) || null;
}

export function formatDate(dateStr) {
    return new Date(dateStr + "T00:00:00").toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
    });
}
